function truncate(input, maxLength, suffix = '…', { wordBoundary = false } = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;
  const limit = Math.max(0, maxLength - suffix.length);
  let head = s.slice(0, limit);
  if (wordBoundary && /\S/.test(s[limit] ?? '')) {
    // The cut lands inside a word: drop that partial word.
    head = head.replace(/\S*$/, '');
  }
  if (wordBoundary) head = head.replace(/\s+$/, '');
  return head + suffix;
}

