// Reduce markdown to the text a reader sees: link text stays, URLs and syntax markers go.
function stripMarkdown(input) {
  return String(input)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ') // images: neither alt nor url is read as prose
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1') // inline links -> link text
    .replace(/\[([^\]]*)\]\[[^\]]*\]/g, '$1') // reference links -> link text
    .replace(/^\s*\[[^\]]*\]:.*$/gm, ' ') // link definitions
    .replace(/^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/gm, ' ') // horizontal rules
    .replace(/^\s{0,3}#{1,6}\s+/gm, '') // heading hashes
    .replace(/^\s*>+\s?/gm, '') // blockquote markers
    .replace(/^\s*(?:[-*+]|\d+[.)])\s+/gm, '') // list bullets
    .replace(/`+/g, ' ') // code fences and spans keep their contents
    .replace(/[*_~]/g, ''); // emphasis markers
}

function wordCount(input) {
  const s = stripMarkdown(input).trim();
  if (!s) return 0;
  return s.split(/\s+/).length;
}

