const test = require('node:test');
const assert = require('node:assert');
const { slugify, truncate, wordCount, readingTime } = require('../src/text');

test('cyrillic-slug: slugify transliterates Cyrillic to Latin', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёжик, Щука и Ъ'), 'ezhik-schuka-i');
  // Latin behaviour is unchanged.
  assert.strictEqual(slugify('Hello World'), 'hello-world');
  assert.strictEqual(slugify('  Spaces  everywhere  '), 'spaces-everywhere');
});

test('truncate-word-boundary: wordBoundary never cuts mid-word', () => {
  assert.strictEqual(truncate('the quick brown fox', 12, '…', { wordBoundary: true }), 'the quick…');
  // Cut already at a boundary: nothing extra is dropped.
  assert.strictEqual(truncate('the quick brown fox', 11, '…', { wordBoundary: true }), 'the quick…');
  // A single word longer than the budget leaves only the suffix.
  assert.strictEqual(truncate('supercalifragilistic', 8, '…', { wordBoundary: true }), '…');
  // Default behaviour is unchanged.
  assert.strictEqual(truncate('the quick brown fox', 12), 'the quick b…');
  assert.strictEqual(truncate('abcdefghij', 5), 'abcd…');
  assert.strictEqual(truncate('short', 20, '…', { wordBoundary: true }), 'short');
});

test('word-count-markdown: counts the words a reader sees', () => {
  assert.strictEqual(wordCount('**bold** text'), 2);
  assert.strictEqual(wordCount('[the link text](https://example.com/a/b)'), 3);
  assert.strictEqual(wordCount('# Heading here'), 2);
  assert.strictEqual(wordCount('- item one\n- item two'), 4);
  assert.strictEqual(wordCount('_emphasis_ and ~~strike~~ and `code`'), 5);
  assert.strictEqual(wordCount('![alt words](https://example.com/i.png)'), 0);
  // Plain text is unaffected.
  assert.strictEqual(wordCount('one two three'), 3);
  assert.strictEqual(wordCount('   '), 0);
});

test('reading-time: whole minutes at 200 wpm, minimum 1', () => {
  const words = (n) => Array.from({ length: n }, () => 'word').join(' ');
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('   '), 0);
  assert.strictEqual(readingTime('one'), 1);
  assert.strictEqual(readingTime(words(200)), 1);
  assert.strictEqual(readingTime(words(201)), 2);
  assert.strictEqual(readingTime(words(1000)), 5);
});

