  assert.strictEqual(escapeHtml('<a href="x">A & B</a>'), '&lt;a href=&quot;x&quot;&gt;A &amp; B&lt;/a&gt;');
  assert.strictEqual(escapeHtml("it's"), 'it&#39;s');
  // The ampersand of an entity we produced is not escaped a second time.
